shape=[(0,2),(1,0),(1,1),(2,0)]  # seed cells relative to min
P=[[0]*C for _ in range(R)]
for r in range(R):
    for c in range(C):
        ok=True
        for dr,dc in shape:
            nr,nc=r+dr,c+dc
            if not(0<=nr<R and 0<=nc<C) or I[nr][nc]!=0:
                ok=False;break
        if ok:
            for dr,dc in shape:
                P[r+dr][c+dc]=4
mism=[(r,c,O[r][c],P[r][c]) for r in range(R) for c in range(C) if P[r][c]!=O[r][c]]
print("mismatch:",len(mism),mism[:20])

mism=[(r,c,I[r][c],O[r][c],P[r][c]) for r in range(R) for c in range(C) if I[r][c]==0 and O[r][c]!=P[r][c]]
print("mismatch on zeros:",len(mism))
for m in mism[:30]: print(m)
